{"query": "mutation {
  bulkOperationRunQuery(
    query: """
    {
      products(query: "status:active AND updated_at:>='2024-05-01' AND updated_at:<'2025-05-01'") {
        edges {
          node {
            id
            title
            handle
            description
            vendor
            productType
            tags
            status
            createdAt
            updatedAt
            publishedAt
            totalInventory
            variants {
              edges {
                node {
                  id
                  title
                  sku
                  barcode
                  price
                  compareAtPrice
                  inventoryQuantity

                }
              }
            }
            images {
              edges {
                node {
                  id
                  url
                  altText
                  width
                  height
                }
              }
            }

          }
        }
      }
    }
    """
  ) {
    bulkOperation {
      id
      status
    }
    userErrors {
      field
      message
    }
  }
}
", "variables": null, "operationName": null}

{"query": "query {
  currentBulkOperation {
    id
    status
    errorCode
    createdAt
    completedAt
    objectCount
    fileSize
    url
    partialDataUrl
  }
}
", "variables": null, "operationName": null}

